package com.example.riskplatform.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component @RequiredArgsConstructor public class JwtAuthFilter extends OncePerRequestFilter{private final JwtUtil jwt;private final CustomUserDetailsService uds;protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String a=req.getHeader("Authorization");if(a!=null&&a.startsWith("Bearer ")&&SecurityContextHolder.getContext().getAuthentication()==null){try{String u=jwt.parseUsername(a.substring(7));UserDetails d=uds.loadUserByUsername(u);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}}chain.doFilter(req,res);}}
